#!/bin/bash
set -e

here=$(dirname "$(readlink -f "$0")")/..
temp=$(mktemp -d)
trap 'rm -rf "$temp"' EXIT

agbcc_repo="https://github.com/notyourav/agbcc.git"
agbcc_branch="cp"

git clone --branch "$agbcc_branch" "$agbcc_repo" "$temp"

cd "$temp"

# agbcc's configure scripts are generated by autoconf 2.13 and use
# `main(){return(0);}` for the compiler sanity check. GCC 15+ defaults to
# -std=gnu23, where implicit int is an error, so configure wrongly reports
# "C compiler cannot create executables". Add the missing return type.
sed -i 's/^main(){return(0);}/int main(){return(0);}/' \
    gcc_arm/configure g++/configure g++_arm/configure

# Build the GCC 2.95 sources in gnu11 mode (as the host agbcc Makefile
# already does) instead of GCC's gnu23 default, and keep diagnostics that
# became errors in newer GCC versions non-fatal.
agbcc_cflags="-std=gnu11 -fcommon -Wno-implicit-function-declaration -Wno-error=incompatible-pointer-types -Wno-error=int-conversion"

sed -i "s/^CFLAGS = -g -Wno-implicit-function-declaration$/CFLAGS = -g $agbcc_cflags/" \
    gcc_arm/Makefile.in g++_arm/Makefile.in
sed -i "s/^CFLAGS = -g3 -Wno-implicit-function-declaration$/CFLAGS = -g3 $agbcc_cflags/" \
    g++/Makefile.in

for configure in gcc_arm/configure g++/configure g++_arm/configure; do
    if ! grep -q '^int main(){return(0);}' "$configure"; then
        echo "error: failed to patch $configure" >&2
        exit 1
    fi
done

for makefile in gcc_arm/Makefile.in g++/Makefile.in g++_arm/Makefile.in; do
    if ! grep -q -- '-std=gnu11' "$makefile"; then
        echo "error: failed to patch $makefile" >&2
        exit 1
    fi
done

./build.sh
./install.sh "$here"
